package com.jnapanam.sportszone.tournament.controller;import com.jnapanam.sportszone.tournament.dto.*;import com.jnapanam.sportszone.tournament.service.TournamentService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/tournaments")public class TournamentController{private final TournamentService service;public TournamentController(TournamentService s){service=s;}@GetMapping("/organizer-applications/me")public List<OrganizerApplicationResponse>myApplications(Authentication a){return service.myApplications(user(a));}@PostMapping("/organizer-applications")@ResponseStatus(HttpStatus.CREATED)public OrganizerApplicationResponse apply(Authentication a,@Valid@RequestBody OrganizerApplicationRequest r){return service.apply(user(a),r);}@PostMapping("/{id}/teams")@ResponseStatus(HttpStatus.CREATED)public TeamResponse register(Authentication a,@PathVariable UUID id,@Valid@RequestBody TeamRegistrationRequest r){return service.register(user(a),id,r);}@GetMapping("/teams/me")public List<TeamResponse>mine(Authentication a){return service.mine(user(a));}private static UUID user(Authentication a){return UUID.fromString(a.getName());}}
